package com.ruoyi.boost;
import java.util.*;
import java.time.LocalDateTime;
import javax.sql.DataSource;
import org.h2.jdbcx.JdbcDataSource;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.extension.ExtendWith;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.*;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.test.context.ContextConfiguration;
import org.springframework.test.context.junit.jupiter.SpringExtension;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;
import org.springframework.mock.web.MockMultipartFile;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.boost.BoostDb.*;
@ExtendWith(SpringExtension.class) @ContextConfiguration(classes=BoostRewardsTest.Config.class)
class BoostRewardsTest {
 @Configuration @EnableTransactionManagement static class Config {
  @Bean DataSource dataSource(){JdbcDataSource d=new JdbcDataSource();d.setURL("jdbc:h2:mem:rewards;MODE=MySQL;DB_CLOSE_DELAY=-1");initialize(d);return d;}
  static void initialize(DataSource d){new ResourceDatabasePopulator(new ClassPathResource("boost/schema.sql")).execute(d);BoostDb db=new BoostDb(new JdbcTemplate(d));BoostMigrations.migrate(db);db.template().execute("CREATE TABLE IF NOT EXISTS sys_user(user_id BIGINT PRIMARY KEY,status VARCHAR(1),del_flag VARCHAR(1))");if(db.count("SELECT COUNT(*) FROM sys_user WHERE user_id=1")==0)db.run("INSERT INTO sys_user VALUES (1,'0','0')");}
  @Bean JdbcTemplate jdbc(DataSource d){return new JdbcTemplate(d);}
  @Bean PlatformTransactionManager tx(DataSource d){return new DataSourceTransactionManager(d);}
  @Bean BoostDb db(JdbcTemplate j){return new BoostDb(j);}
  @Bean BoostAuth auth(BoostDb d){return new BoostAuth(d);}
  @Bean BoostRewardsMedia media(BoostDb d){return new BoostRewardsMedia(d);}
  @Bean BoostRewards rewards(BoostDb d,BoostRewardsMedia m){return new BoostRewards(d,m);}
 }
 @Autowired BoostDb db;@Autowired BoostAuth auth;@Autowired BoostRewards rewards;@Autowired BoostRewardsMedia media;@Autowired PlatformTransactionManager tx;
 @org.junit.jupiter.api.io.TempDir java.nio.file.Path directory;long member,other;String image;
 @BeforeEach void prepare()throws Exception{ReflectionTestUtils.setField(media,"directory",directory.toString());ReflectionTestUtils.setField(rewards,"drawEnabled",true);member=member();other=member();java.io.ByteArrayOutputStream b=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(4,4,1),"png",b);image=str((Map<String,Object>)media.upload(1,new MockMultipartFile("file","public.png","image/png",b.toByteArray())),"url");}
 long member(){return num((Map<String,Object>)auth.register(map("username","rw_"+UUID.randomUUID().toString().replace("-","").substring(0,12),"password","RewardFixture123!","nickname","积分测试")).get("user"),"id");}
 Map<String,Object> goods(String kind,int stock){return map("title","测试奖品","kind",kind,"badgeCode","BADGE".equals(kind)?"B_"+UUID.randomUUID().toString().replace("-","").substring(0,30).toUpperCase(Locale.ROOT):"","image",image,"description","隔离测试免费积分商品","pointsCost",10,"stock",stock,"status","ACTIVE");}
 long product(String kind,int stock){return num((Map<String,Object>)rewards.saveGoods(1,null,goods(kind,stock)),"id");}
 Map<String,Object> body(){return map("requestKey",UUID.randomUUID().toString(),"expectedPointsCost",10,"expectedRevision",1);}
 void grant(long who,int amount){rewards.grant(1,who,map("requestKey",UUID.randomUUID().toString(),"amount",amount,"note","免费测试奖励"));}
 long balance(){return num((Map<String,Object>)rewards.points(member,Map.of()),"balance");}
 long activity(List<Map<String,Object>>pool){return num((Map<String,Object>)rewards.saveActivity(1,null,map("title","免费活动测试","cover",image,"description","测试环境免费积分活动","pointsCost",2,"startsAt",LocalDateTime.now().minusDays(1).withNano(0).toString(),"endsAt",LocalDateTime.now().plusDays(1).withNano(0).toString(),"status","ACTIVE","prizes",pool)),"id");}
 @Test void freeGrantIsAuditedIdempotentAndCannotOverflow(){Map<String,Object>b=map("requestKey",UUID.randomUUID().toString(),"amount",100,"note","免费社区奖励");rewards.grant(1,member,b);rewards.grant(1,member,b);assertEquals(100,balance());assertEquals(1,db.count("SELECT COUNT(*) FROM boost_points_entry WHERE member_id=?",member));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_audit WHERE action='rewards:free-grant' AND target_id=?",member));b.put("amount",101);assertThrows(BoostException.class,()->rewards.grant(1,member,b));assertEquals(100,balance());db.run("UPDATE boost_points_account SET balance=1000000000 WHERE member_id=?",member);assertThrows(BoostException.class,()->grant(member,1));assertEquals(1000000000,balance());}
 @Test void badgePersistsPubliclyAndDuplicateOwnershipDoesNotConsume(){long g=product("BADGE",3);grant(member,100);Map<String,Object>b=body();long o=num((Map<String,Object>)rewards.redeem(member,g,b),"id");assertEquals(o,num((Map<String,Object>)rewards.redeem(member,g,b),"id"));assertEquals(90,balance());assertEquals(2,num(rewards.good(g,true),"stock"));assertEquals(1,((List<?>)rewards.badges(member)).size());assertEquals("COMPLETED",str(rewards.detail(member,o),"status"));assertThrows(BoostException.class,()->rewards.redeem(member,g,body()));assertEquals(90,balance());assertEquals(2,num(rewards.good(g,true),"stock"));assertThrows(BoostException.class,()->rewards.detail(other,o));}
 @Test void insufficientPointsAndOfflineGoodsLeaveNoPartialWrites(){long g=product("PHYSICAL",1);assertThrows(BoostException.class,()->rewards.redeem(member,g,body()));assertEquals(1,num(rewards.good(g,true),"stock"));assertEquals(0,db.count("SELECT COUNT(*) FROM boost_reward_order WHERE member_id=?",member));grant(member,100);db.run("UPDATE boost_reward_goods SET status='DRAFT' WHERE id=?",g);assertThrows(BoostException.class,()->rewards.redeem(member,g,body()));assertEquals(100,balance());assertThrows(BoostException.class,()->rewards.good(g,false));}
 @Test void physicalOrderRequiresAddressThenShippingThenOwnerReceipt(){long g=product("PHYSICAL",1);grant(member,100);long id=num((Map<String,Object>)rewards.redeem(member,g,body()),"id");assertEquals("WAIT_ADDRESS",str(rewards.detail(member,id),"status"));assertThrows(BoostException.class,()->rewards.ship(1,id,map("carrier","测试物流","trackingNo","TEST001")));assertThrows(BoostException.class,()->rewards.receive(member,id));Map<String,Object>a=map("recipient","测试收件人","phone","13800000000","address","测试省测试市测试区测试街道1号");assertThrows(BoostException.class,()->rewards.address(other,id,a));Map<String,Object>bad=new HashMap<>(a);bad.put("phone","123");assertThrows(BoostException.class,()->rewards.address(member,id,bad));rewards.address(member,id,a);rewards.address(member,id,a);assertEquals("WAIT_SHIP",str(rewards.detail(member,id),"status"));Map<String,Object>ship=map("carrier","测试物流","trackingNo","TEST001");rewards.ship(1,id,ship);rewards.ship(1,id,ship);assertThrows(BoostException.class,()->rewards.ship(1,id,map("carrier","另一物流","trackingNo","CHANGED001")));assertThrows(BoostException.class,()->rewards.address(member,id,a));assertThrows(BoostException.class,()->rewards.receive(other,id));rewards.receive(member,id);rewards.receive(member,id);assertEquals("COMPLETED",str(rewards.detail(member,id),"status"));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_audit WHERE action='rewards:ship' AND target_id=?",id));assertFalse(rewards.detail(member,id).containsKey("requestHash"));}
 @Test void malformedGoodsImagesAndActivityPoolsAreRejected(){Map<String,Object>b=goods("BADGE",1);b.put("badgeCode","<script>");assertThrows(BoostException.class,()->rewards.saveGoods(1,null,b));for(String bad:List.of("/boost-media/"+"a".repeat(32)+".png","https://external.example/image.png","/boost-reward-media/../../x"))assertThrows(BoostException.class,()->media.validate(bad));assertThrows(BoostException.class,()->media.upload(1,new MockMultipartFile("file","x.png","image/png","not image".getBytes())));long g=product("PHYSICAL",3);assertThrows(BoostException.class,()->activity(List.of(map("goodsId",g,"weight",1),map("goodsId",g,"weight",1))));}
 @Test void staleOperatorStockCannotRestoreConcurrentConsumedInventory(){Map<String,Object>b=goods("PHYSICAL",2);long g=num((Map<String,Object>)rewards.saveGoods(1,null,b),"id");grant(member,100);b.put("expectedStock",2);rewards.redeem(member,g,body());BoostException e=assertThrows(BoostException.class,()->rewards.saveGoods(1,g,b));assertEquals(409,e.code);assertEquals(1,num(rewards.good(g,true),"stock"));b.put("expectedStock",1);b.put("stock",3);rewards.saveGoods(1,g,b);assertEquals(3,num(rewards.good(g,true),"stock"));}
 @Test void drawDisabledExpiredOrInsufficientDoesNotCharge(){long g=product("PHYSICAL",9),a=activity(List.of(map("goodsId",g,"weight",1),map("goodsId",null,"weight",1)));Map<String,Object>b=body();b.put("count",5);b.put("expectedPointsCost",2);grant(member,9);assertThrows(BoostException.class,()->rewards.draw(member,a,b));assertEquals(9,balance());grant(member,100);ReflectionTestUtils.setField(rewards,"drawEnabled",false);assertThrows(BoostException.class,()->rewards.draw(member,a,b));assertEquals(109,balance());ReflectionTestUtils.setField(rewards,"drawEnabled",true);db.run("UPDATE boost_reward_activity SET ends_at=? WHERE id=?",java.sql.Timestamp.valueOf(LocalDateTime.now().minusHours(1)),a);assertThrows(BoostException.class,()->rewards.draw(member,a,b));assertEquals(0,db.count("SELECT COUNT(*) FROM boost_reward_draw WHERE member_id=?",member));assertEquals(109,balance());}
 @Test void fiveDrawsAreExactlyChargedSavedAndRetryReturnsSameSnapshot(){long g=product("PHYSICAL",100),a=activity(List.of(map("goodsId",g,"weight",5),map("goodsId",null,"weight",1)));grant(member,100);Map<String,Object>b=body();b.put("count",5);b.put("expectedPointsCost",2);Map<String,Object>r=(Map<String,Object>)rewards.draw(member,a,b);assertEquals(5,((List<?>)r.get("results")).size());assertEquals(10,num(r,"pointsSpent"));assertEquals(90,balance());Map<String,Object>retry=(Map<String,Object>)rewards.draw(member,a,b);assertEquals(r.get("results"),retry.get("results"));assertEquals(r.get("id"),retry.get("id"));long wins=((List<Map<String,Object>>)r.get("results")).stream().filter(x->x.get("orderId")!=null).count();assertEquals(wins,db.count("SELECT COUNT(*) FROM boost_reward_order WHERE member_id=?",member));assertEquals(100-wins,num(rewards.good(g,true),"stock"));for(Map<String,Object>x:(List<Map<String,Object>>)r.get("results")){double sum=((List<Map<String,Object>>)x.get("odds")).stream().mapToDouble(p->((Number)p.get("probability")).doubleValue()).sum();assertEquals(1.0,sum,0.000000001);}b.put("count",1);assertThrows(BoostException.class,()->rewards.draw(member,a,b));assertEquals(90,balance());}
 @Test void fiveDrawPartialStockExhaustionRollsBackEverything(){long one=product("PHYSICAL",1),two=product("PHYSICAL",1),a=activity(List.of(map("goodsId",one,"weight",1),map("goodsId",two,"weight",1)));grant(member,100);Map<String,Object>b=body();b.put("count",5);b.put("expectedPointsCost",2);assertThrows(BoostException.class,()->rewards.draw(member,a,b));assertEquals(100,balance());assertEquals(1,num(rewards.good(one,true),"stock"));assertEquals(1,num(rewards.good(two,true),"stock"));assertEquals(0,db.count("SELECT COUNT(*) FROM boost_reward_order WHERE member_id=?",member));assertEquals(0,db.count("SELECT COUNT(*) FROM boost_reward_draw WHERE member_id=?",member));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_points_entry WHERE member_id=?",member));}
 @Test void ownedBadgesAndEmptyStockAreDisclosedAsUnavailable(){long g=product("BADGE",2),a=activity(List.of(map("goodsId",g,"weight",1),map("goodsId",null,"weight",1)));grant(member,100);rewards.redeem(member,g,body());Map<String,Object>activity=rewards.activity(a,member,false);Map<String,Object>p=((List<Map<String,Object>>)activity.get("prizes")).get(0);assertEquals(false,p.get("available"));assertEquals(0.0,((Number)p.get("probability")).doubleValue());Map<String,Object>b=body();b.put("count",5);b.put("expectedPointsCost",2);Map<String,Object>draw=(Map<String,Object>)rewards.draw(member,a,b);for(Map<String,Object>r:(List<Map<String,Object>>)draw.get("results"))assertEquals("NONE",r.get("kind"));assertEquals(1,num(rewards.good(g,true),"stock"));}
 @Test void suspendedMembersCannotSpendGrantOrExposeBadges(){long g=product("BADGE",2);grant(member,100);rewards.redeem(member,g,body());db.run("UPDATE boost_member SET status='BLOCKED' WHERE id=?",member);assertThrows(BoostException.class,()->grant(member,1));assertThrows(BoostException.class,()->rewards.redeem(member,g,body()));assertThrows(BoostException.class,()->rewards.points(member,Map.of()));assertEquals(0,((List<?>)rewards.badges(member)).size());}
 @Test void migrationReplaysWithoutChangingExistingBalances()throws Exception{grant(member,100);BoostMigrations.migrate(db);BoostMigrations.verifyApplied(db);assertEquals(100,balance());assertEquals(0,db.count("SELECT COUNT(*) FROM boost_ledger WHERE member_id=?",member));assertEquals(1,db.count("SELECT COUNT(*) FROM boost_points_entry WHERE member_id=?",member));}
 @Test void changedPriceOrPoolRequiresNewConfirmationAndHistoryKeepsNames(){long g=product("PHYSICAL",20),a=activity(List.of(map("goodsId",g,"weight",1),map("goodsId",null,"weight",1)));grant(member,100);Map<String,Object>r=body();db.run("UPDATE boost_reward_goods SET points_cost=50,revision=revision+1 WHERE id=?",g);assertEquals(409,assertThrows(BoostException.class,()->rewards.redeem(member,g,r)).code);assertEquals(100,balance());Map<String,Object>d=body();d.put("count",5);d.put("expectedPointsCost",2);db.run("UPDATE boost_reward_activity SET revision=revision+1 WHERE id=?",a);assertEquals(409,assertThrows(BoostException.class,()->rewards.draw(member,a,d)).code);assertEquals(100,balance());d.put("expectedRevision",2);Map<String,Object>result=(Map<String,Object>)rewards.draw(member,a,d);db.run("DELETE FROM boost_reward_prize WHERE activity_id=?",a);Map<String,Object>retry=(Map<String,Object>)rewards.draw(member,a,d);assertEquals(result.get("results"),retry.get("results"));for(Map<String,Object>x:(List<Map<String,Object>>)retry.get("results"))for(Map<String,Object>p:(List<Map<String,Object>>)x.get("odds")){assertTrue(p.containsKey("goodsId"));assertTrue(p.containsKey("position"));assertFalse(str(p,"title").isEmpty());assertFalse(str(p,"kind").isEmpty());}}
}
